// A declined collection, in three dispositions encoded by the arguments:
// terminal (uncollectible), no next attempt (charging stops until the
// customer fixes their card), or a next attempt (still dunning). Being
// overdue is a reading of the clock, the delinquency axis; only a terminal
// outcome closes collection.
func (q *Queries) RecordUsageCollectionFailure(ctx context.Context, arg RecordUsageCollectionFailureParams) (int64, error) {
	result, err := q.db.Exec(ctx, recordUsageCollectionFailure,
		arg.Terminal,
		arg.Now,
		arg.NextAttemptAt,
		arg.LastPaymentError,
		arg.MerchantID,
		arg.ID,
		arg.AttemptID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resumeStoppedUsageCollection = `-- name: ResumeStoppedUsageCollection :execrows
UPDATE billing.orders
SET next_collection_attempt_at = $1::timestamptz,
    updated_at = $1::timestamptz
WHERE merchant_id = $2::uuid AND customer_id = $3::uuid AND currency = $4
  AND origin = 'usage' AND status = 'open' AND amount_paid < total
  AND collection_method = 'charge_automatically'
  AND collection_failure_count > 0 AND next_collection_attempt_at IS NULL
`

type ResumeStoppedUsageCollectionParams struct {
	Now        time.Time
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
}

// A payer designating a collection card did what a stopped collection asked:
// its usage orders are due again at once. Uncollectible ones need the
// merchant, and live collections belong to their verifier.
func (q *Queries) ResumeStoppedUsageCollection(ctx context.Context, arg ResumeStoppedUsageCollectionParams) (int64, error) {
	result, err := q.db.Exec(ctx, resumeStoppedUsageCollection,
		arg.Now,
		arg.MerchantID,
		arg.CustomerID,
		arg.Currency,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startUsageCollection = `-- name: StartUsageCollection :execrows
UPDATE billing.orders
SET status = 'processing', payment_status = 'processing', attempt_id = $1::uuid,
    payment_method_id = $2::uuid, psp_id = $3::uuid,
    next_collection_attempt_at = NULL, uncollectible_at = NULL, updated_at = $4::timestamptz
WHERE merchant_id = $5::uuid AND id = $6::uuid AND origin = 'usage'
  AND status IN ('open', 'uncollectible') AND amount_paid < total
`

type StartUsageCollectionParams struct {
	AttemptID       uuid.UUID
	PaymentMethodID uuid.UUID
	PspID           uuid.UUID
	Now             time.Time
	MerchantID      uuid.UUID
	ID              uuid.UUID
}

// Points the usage order at its one live collection, its attempt. Collecting
// an uncollectible order reopens it.
func (q *Queries) StartUsageCollection(ctx context.Context, arg StartUsageCollectionParams) (int64, error) {
	result, err := q.db.Exec(ctx, startUsageCollection,
		arg.AttemptID,
		arg.PaymentMethodID,
		arg.PspID,
		arg.Now,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const stopUsageCollection = `-- name: StopUsageCollection :execrows
UPDATE billing.orders
SET collection_failure_count = collection_failure_count + 1,
    collection_failed_at = COALESCE(collection_failed_at, $1::timestamptz),
    next_collection_attempt_at = NULL,
    last_payment_error = $2::jsonb,
    updated_at = $1::timestamptz
WHERE merchant_id = $3::uuid AND id = $4::uuid AND origin = 'usage' AND status = 'open'
`

type StopUsageCollectionParams struct {
	Now              time.Time
	LastPaymentError []byte
	MerchantID       uuid.UUID
	ID               uuid.UUID
}

// The collection card carries no customer agreement for a merchant-initiated
// charge: charging stops until the customer acts, as a fix-your-card decline
// stops it.
func (q *Queries) StopUsageCollection(ctx context.Context, arg StopUsageCollectionParams) (int64, error) {
	result, err := q.db.Exec(ctx, stopUsageCollection,
		arg.Now,
		arg.LastPaymentError,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sumOwedOrderClaims = `-- name: SumOwedOrderClaims :one
SELECT COALESCE(SUM(total - amount_paid), 0)::bigint AS amount
FROM billing.orders
WHERE merchant_id = $1::uuid AND customer_id = $2::uuid AND currency = $3::text
  AND origin = 'usage' AND status IN ('open', 'processing', 'uncollectible') AND amount_paid < total
`

type SumOwedOrderClaimsParams struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
}

func (q *Queries) SumOwedOrderClaims(ctx context.Context, arg SumOwedOrderClaimsParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumOwedOrderClaims, arg.MerchantID, arg.CustomerID, arg.Currency)
	var amount int64
	err := row.Scan(&amount)
	return amount, err
}

const sumPendingOwedItemAmountBySourceInPeriod = `-- name: SumPendingOwedItemAmountBySourceInPeriod :many
SELECT COALESCE(NULLIF(metadata ->> 'source', ''), source_type)::text AS source,
       COALESCE(SUM(amount), 0)::bigint AS amount,
       COUNT(*)::bigint AS item_count
FROM billing.owed_items
WHERE merchant_id = $1::uuid AND customer_id = $2::uuid AND currency = $3
  AND order_id IS NULL AND status = 'pending'
  AND accrued_at >= $4::timestamptz
  AND accrued_at < $5::timestamptz
GROUP BY 1
ORDER BY 1 ASC
`

type SumPendingOwedItemAmountBySourceInPeriodParams struct {
	MerchantID     uuid.UUID
	CustomerID     uuid.UUID
	Currency       string
	PeriodStartsAt time.Time
	PeriodEndsAt   time.Time
}

type SumPendingOwedItemAmountBySourceInPeriodRow struct {
	Source    string
	Amount    int64
	ItemCount int64
}

// A period's pending charges per accrual source: a usage order's lines.
// Metered accruals carry their rating identity (e.g. metered:<meter>) in
// metadata->>'source'.
func (q *Queries) SumPendingOwedItemAmountBySourceInPeriod(ctx context.Context, arg SumPendingOwedItemAmountBySourceInPeriodParams) ([]SumPendingOwedItemAmountBySourceInPeriodRow, error) {
	rows, err := q.db.Query(ctx, sumPendingOwedItemAmountBySourceInPeriod,
		arg.MerchantID,
		arg.CustomerID,
		arg.Currency,
		arg.PeriodStartsAt,
		arg.PeriodEndsAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SumPendingOwedItemAmountBySourceInPeriodRow
	for rows.Next() {
		var i SumPendingOwedItemAmountBySourceInPeriodRow
		if err := rows.Scan(&i.Source, &i.Amount, &i.ItemCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

