const usageRecoveryAccounts = `-- name: UsageRecoveryAccounts :many
SELECT p.id, p.rail FROM billing.psps p
WHERE p.merchant_id = $1::uuid AND p.rail IN ('nmi', 'stripe')
  AND p.environment = (SELECT environment FROM billing.psps WHERE merchant_id = p.merchant_id AND id = $2::uuid)
ORDER BY p.id
`

type UsageRecoveryAccountsParams struct {
	MerchantID uuid.UUID
	RoutedPsp  uuid.UUID
}

type UsageRecoveryAccountsRow struct {
	ID   uuid.UUID
	Rail string
}

// A different chosen card does not hide a prior account's paid order, even
// if that card was added after the backup. Inspect every known card account
// in this deployment environment; unrelated rails cannot collect it.
func (q *Queries) UsageRecoveryAccounts(ctx context.Context, arg UsageRecoveryAccountsParams) ([]UsageRecoveryAccountsRow, error) {
	rows, err := q.db.Query(ctx, usageRecoveryAccounts, arg.MerchantID, arg.RoutedPsp)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsageRecoveryAccountsRow
	for rows.Next() {
		var i UsageRecoveryAccountsRow
		if err := rows.Scan(&i.ID, &i.Rail); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usageRecoveryAllocationTotal = `-- name: UsageRecoveryAllocationTotal :one
SELECT COALESCE(sum(l.amount), 0)::bigint AS amount,
  COALESCE(bool_and(l.id IS NOT NULL AND l.order_id IS NOT DISTINCT FROM p.order_id AND l.customer_id IS NOT DISTINCT FROM p.customer_id
    AND l.currency = p.currency AND l.currency = $1::text
    AND l.transfer_type = 'owed_payment' AND l.operation IN ('invoice_payment', 'manual_invoice_payment')
    AND l.amount > 0 AND p.amount >= l.amount), true)::boolean AS consistent
FROM billing.payments p LEFT JOIN billing.ledger_transfers l
  ON l.merchant_id = p.merchant_id AND l.id = p.ledger_transfer_id
WHERE p.merchant_id = $2::uuid AND p.order_id = $3::uuid AND p.status = 'succeeded' AND p.deleted_at IS NULL
`

type UsageRecoveryAllocationTotalParams struct {
	Currency   string
	MerchantID uuid.UUID
	OrderID    uuid.UUID
}

type UsageRecoveryAllocationTotalRow struct {
	Amount     int64
	Consistent bool
}

// The order's retained paid amount must be explained by its allocations,
// including native rounding (provider amount can exceed the allocated debt).
func (q *Queries) UsageRecoveryAllocationTotal(ctx context.Context, arg UsageRecoveryAllocationTotalParams) (UsageRecoveryAllocationTotalRow, error) {
	row := q.db.QueryRow(ctx, usageRecoveryAllocationTotal, arg.Currency, arg.MerchantID, arg.OrderID)
	var i UsageRecoveryAllocationTotalRow
	err := row.Scan(&i.Amount, &i.Consistent)
	return i, err
}

const usageRecoveryHasOtherPayment = `-- name: UsageRecoveryHasOtherPayment :one
SELECT EXISTS(SELECT 1 FROM billing.payments p
    WHERE p.merchant_id = $1::uuid AND p.psp_id = $2::uuid AND p.transaction_id = $3::text
      AND NOT EXISTS (SELECT 1 FROM billing.orders o WHERE o.merchant_id = p.merchant_id AND o.id = p.order_id AND o.origin = 'usage'))::boolean
`

type UsageRecoveryHasOtherPaymentParams struct {
	MerchantID    uuid.UUID
	PspID         uuid.UUID
	TransactionID string
}

// A transaction already allocated to a subscription or purchase cannot also
// settle a usage order, including soft-deleted financial rows.
func (q *Queries) UsageRecoveryHasOtherPayment(ctx context.Context, arg UsageRecoveryHasOtherPaymentParams) (bool, error) {
	row := q.db.QueryRow(ctx, usageRecoveryHasOtherPayment, arg.MerchantID, arg.PspID, arg.TransactionID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

